void ui_ScreenSmsListDraft_win_focus(lv_obj_t * win,void * param)
{
    list_draft_win_param_t * p_param;

    p_param             = (list_draft_win_param_t *) lv_obj_get_user_data(win);
    lv_obj_t *      ui_screen = NULL;

    if (p_param->ui_main)
        ui_screen = p_param->ui_main;
    else if (p_param->ui_remind)
        ui_screen = p_param->ui_remind;

    if (ui_screen) {
        lv_disp_load_scr(ui_screen);
        }

    if (ui_screen == p_param->ui_main) {
        lv_obj_t *      list = get_sms_list_draft_select_list_obj(ui_screen);

        ;
        uint32_t        child_cnt = lv_obj_get_child_cnt(list);
        uint32_t        child_id = get_list_child_focused_id(list,child_cnt);
        lv_obj_t *      get_focus_obj = NULL;
        lv_obj_t *      label;

        get_focus_obj       = lv_obj_get_child(list,child_id);

        if (get_focus_obj) {
            label               = lv_obj_get_child(get_focus_obj,1);
            app_fp_play_tts_menu(lv_label_get_text(label));
            }
        }

    p_param->focus_status = 1;
}

